L["/copy puts the text of whatever is under your cursor in a box you can copy from. /copy followed by a frame name copies that frame's text instead."] = "/copy는 커서 아래에 있는 텍스트를 복사할 수 있는 상자에 넣습니다. /copy 뒤에 프레임 이름을 쓰면 그 프레임의 텍스트를 복사합니다."
L["/nf ab <name>: imports a saved action bar set; /nf ab lists them"] = "/nf ab <이름>: 저장된 행동 단축바 세트를 가져옵니다. /nf ab는 목록을 표시합니다"
L["/nf badges id: your badge claim code"] = "/nf badges id: 배지 수령 코드"
L["/nf bars save, restore, test or delete <name>: your action bar sets; /nf bars list lists them"] = "/nf bars save, restore, test 또는 delete <이름>: 행동 단축바 세트 관리. /nf bars list는 목록을 표시합니다"
