L["30, while the game is not in focus"] = "30, 게임 창이 비활성일 때"
L[": copy ID or Wowhead link"] = ": ID 또는 Wowhead 링크 복사"
L[": mail expiring soon on "] = ": 곧 만료되는 우편 위치:"
L["; buys at vendors"] = "; 상인에게 구매"
L["<AFK>"] = "<자리 비움>"
L["<DND>"] = "<다른 용무 중>"
L["[Where?]"] = "[어디?]"
L["A /thank to everyone around you when the game cannot name the caster."] = "시전자를 알 수 없을 때 주변 모두에게 /thank를 보냅니다."
L["A [Where?] link after a whisper from someone whose zone is not known. Clicking it runs a /who for them and prints their zone; their next messages are tagged."] = "위치를 모르는 상대의 귓속말 뒤에 [어디?] 링크를 붙입니다. 클릭하면 /who를 실행해 지역을 출력하고, 이후 메시지에 표시합니다."
L["A banner and a sound when one of them joins your group."] = "그중 한 명이 파티에 합류하면 배너와 소리로 알립니다."
L["A bar at the threat where you would pull aggro, so the gap to it is easy to read."] = "어그로를 끄는 위협 수준에 막대를 표시해 남은 차이를 쉽게 볼 수 있습니다."
L["A bar for your target's swings, restarted by each physical hit you take while it is targeting you, and shortened when it parries. It is an estimate: the game does not say who hit you or with what, so other attackers, physical specials and bleed ticks restart it too."] = "대상의 공격 주기 막대로, 대상이 나를 노릴 때 물리 공격을 받을 때마다 다시 시작하고 대상이 막으면 줄어듭니다. 게임이 누가 무엇으로 때렸는지 알려주지 않으므로 추정치이며, 다른 공격자, 물리 특수 기술, 출혈 피해도 다시 시작시킵니다."
L["A bar left out is not touched by an import."] = "제외한 바는 가져오기의 영향을 받지 않습니다."
L["A bar per group member with their level and how far through it they are. Every member running Naowh Forever shares their experience, even with this off; anyone else shows their level. Updates wait until combat ends. Move it in the HUD Editor."] = "파티원마다 레벨과 진행도를 막대로 표시합니다. Naowh Forever를 쓰는 파티원은 이 옵션이 꺼져 있어도 경험치를 공유하고, 나머지는 레벨만 표시됩니다. 전투가 끝날 때까지 업데이트를 미룹니다. HUD 편집기에서 옮기세요."
L["A bar with the name, a turn arrow and the distance, while a waypoint is set."] = "경유지가 설정되어 있는 동안 이름, 방향 화살표, 거리를 막대로 표시합니다."
L["A batch of ten, four done, as it shows while you craft."] = "제작 중 표시되는 모습: 10개 중 4개 완료."
L["A black outline round the clock."] = "시계 주위에 검은 외곽선."
L["A black outline round the FPS / MS readout and the counts, in place of the soft shadow."] = "부드러운 그림자 대신 FPS / MS 표시와 숫자 주위에 검은 외곽선."
L["A black outline round the text, in place of the soft shadow."] = "부드러운 그림자 대신 텍스트 주위에 검은 외곽선."
L["A button per set: click to equip, Shift-click to save what you wear into it, Ctrl-click to rename it, right-click to change its icon, and + to save a new one. The set you wear is outlined. Move it in the HUD Editor."] = "세트마다 버튼 하나: 클릭하면 착용, Shift+클릭하면 현재 장비를 저장, Ctrl+클릭하면 이름 변경, 오른쪽 클릭하면 아이콘 변경, +로 새 세트를 저장합니다. 착용 중인 세트는 테두리로 표시됩니다. HUD 편집기에서 옮기세요."
L["A button that flags or unflags you for PvP, showing which you are."] = "PvP 상태를 켜거나 끄고 현재 상태를 보여주는 버튼."
L["A campfire in range and Camp Benefits about to run out."] = "모닥불이 사거리 안에 있고 이로운 야영 효과가 곧 끝남."
L["A campfire in range and no Camp Benefits."] = "모닥불이 사거리 안에 있고 이로운 야영 효과가 없음."
L["A campfire is in range"] = "모닥불이 사거리 안에 있음"
L["A card behind the text, a soft dark fade, or nothing at all."] = "텍스트 뒤에 카드, 부드러운 어두운 그라데이션, 또는 없음."
L["A card over the pin with what it is and how far."] = "핀 위에 무엇인지와 거리를 보여주는 카드."
L["A cast part way through, swept around the ring."] = "링을 따라 회전하는 진행 중인 시전."
L["A cast someone interrupted, held for the fade time."] = "누군가 차단한 시전, 사라짐 시간 동안 유지."
L["A cast while your interrupt is on cooldown, with the tick where it comes back."] = "차단 기술이 재사용 대기 중일 때의 시전, 다시 사용 가능한 시점 표시."
L["A cast while your interrupt is ready."] = "차단 기술이 준비되었을 때의 시전."
L["A cast you cannot interrupt, with its shield."] = "차단할 수 없는 시전, 방패 표시."
L["A character shows up here after you log into it with Instance Tracker on. Track Alts shows the others: rested experience and durability, from the last time that character was logged in."] = "인스턴스 추적기를 켠 상태로 접속한 캐릭터가 여기에 표시됩니다. 부캐릭터 추적은 다른 캐릭터의 휴식 경험치와 내구도를 마지막 접속 기준으로 보여줍니다."
L["A choice among its rewards: pick this one."] = "보상 선택: 이것을 고르세요."
L["A command name can only use letters, numbers and underscores."] = "명령어 이름에는 문자, 숫자, 밑줄만 쓸 수 있습니다."
L["A consumable or personal buff with less time than this left counts as missing."] = "남은 시간이 이보다 짧은 소비용품이나 개인 강화 효과는 없는 것으로 간주합니다."
L["A crosshair at the middle of your screen."] = "화면 가운데에 조준선."
L["A cup beside a healer who is drinking."] = "물을 마시는 치유사 옆에 컵 표시."
L["A custom command can't reload. Type /reload."] = "사용자 명령으로는 재시작할 수 없습니다. /reload를 입력하세요."
L["A dark or light fill and edge behind each line, or none."] = "각 줄 뒤에 어두운 또는 밝은 배경과 테두리, 또는 없음."
L["A dark panel behind the icons."] = "아이콘 뒤의 어두운 패널."
L["A door on each dungeon and raid entrance on the world map, for the sides the Journal lists. Hover it for the levels, click it for a waypoint."] = "도감에 나온 진영 기준으로 세계 지도의 던전 및 공격대 입구마다 문을 표시합니다. 마우스를 올리면 레벨을, 클릭하면 경유지를 설정합니다."
L["A dot on a slot where a better enchant for your level waits: hover it for the advice, click it to ask in Trade."] = "현재 레벨에 더 좋은 마법부여가 있는 칸에 점을 표시합니다. 마우스를 올리면 조언을, 클릭하면 거래 채널에 요청합니다."
L["A fading trail behind the cursor."] = "커서 뒤에 사라지는 잔상."
L["A few quick steps for %s only, its own modules included."] = "%s 전용 간단한 설정 몇 단계 (자체 모듈 포함)."
L["A game that opens when a flight starts and closes when you land."] = "비행이 시작되면 열리고 착륙하면 닫히는 게임."
L["A game to pass the flight: the Quiz or the Aim Trainer. It closes when you land."] = "비행 중 즐길 게임: 퀴즈 또는 조준 훈련. 착륙하면 닫힙니다."
L["A gear set called %s already exists."] = "%s(이)가 이미 장비 세트 이름으로 존재합니다."
L["A glow on the moving edge of the fill."] = "채워지는 부분의 움직이는 끝에 빛 효과."
L["A hidden quest chain across Azeroth: click each thing in the world in turn. It gives a lot of experience, and ends in the Cozy Sleeping Bag; rest in it for a bonus to experience."] = "아제로스 곳곳에 숨겨진 연계 퀘스트: 세계의 물체를 차례로 클릭하세요. 많은 경험치를 주며, 마지막에 아늑한 침낭을 받습니다. 침낭에서 쉬면 경험치 보너스를 얻습니다."
L["A key that opens Group Inspect."] = "파티 살펴보기를 여는 단축키."
L["A key that shows a boss's loot at your cursor."] = "커서 위치에 우두머리의 전리품을 표시하는 단축키."
L["A key that uses this item."] = "이 아이템을 사용하는 단축키."
L["A later point needs it. "] = "나중 포인트에 필요합니다."
L["A later step."] = "이후 단계."
L["A line for each quest you turn in, with the experience and money it gave. Reward items show as their own lines."] = "반납한 퀘스트마다 얻은 경험치와 골드를 한 줄로 표시합니다. 보상 아이템은 별도 줄로 표시됩니다."
L["A line for every reputation gain, from quests and kills alike."] = "퀘스트와 처치로 얻은 모든 평판을 한 줄씩 표시합니다."
L["A line for the experience from each kill. Quest experience is on the quest's own line."] = "처치할 때마다 얻은 경험치를 한 줄로 표시합니다. 퀘스트 경험치는 퀘스트 줄에 표시됩니다."
L["A line from the pin down to a map pin's or corpse's spot."] = "핀에서 지도 핀 또는 시체 위치까지 이어지는 선."
L["A line in chat with the item's link."] = "아이템 링크가 포함된 대화창 메시지."
L["A line in their color on their player tooltip."] = "플레이어 툴팁에 해당 색상으로 한 줄 표시."
L["A line to share them with."] = "공유용 한 줄."
L["A line under the ID saying which keys copy it (Ctrl-Shift-C: copy ID or Wowhead link). Off, the shortcut still works; the line is just not shown."] = "ID 아래에 복사 단축키를 알려주는 줄을 표시합니다 (Ctrl+Shift+C: ID 또는 Wowhead 링크 복사). 꺼도 단축키는 작동하며 줄만 숨겨집니다."
L["A look you do not have yet|r"] = "아직 없는 외형|r"
L["a macro made on this character"] = "이 캐릭터에서 만든 매크로"
L["A macro this character does not have yet: the import makes it."] = "이 캐릭터에 아직 없는 매크로: 가져오기로 생성됩니다."
L["A minimap button that opens %s. /nf%s does the same, and the Top Bar can carry it too. Saved for this computer."] = "%s(을)를 여는 미니맵 버튼. /nf%s도 같은 기능이며 상단 바에도 넣을 수 있습니다. 이 컴퓨터에 저장됩니다."
L["A Naowh weights line, or a WoWSims EP export (in WoWSims: Stat Weights, Copy to Current EP, Export)"] = "Naowh 가중치 줄 또는 WoWSims EP 내보내기 (WoWSims: Stat Weights, Copy to Current EP, Export)"
L["A Naowh weights line, or a WoWSims EP export."] = "Naowh 가중치 줄 또는 WoWSims EP 내보내기."
L["A new session, before any experience."] = "경험치를 얻기 전의 새 세션."
L["A parry by your target took 40% off its swing."] = "대상이 막아서 공격 주기가 40% 줄었습니다."
L["A party of five, a card each."] = "5인 파티, 한 명당 카드 하나."
L["A player's score on their tooltip. One running Naowh Forever shares theirs; anyone else's is read from their gear when you hover them, within inspect range and out of combat."] = "플레이어 툴팁에 점수를 표시합니다. Naowh Forever 사용자는 자신의 점수를 공유하고, 다른 플레이어는 살펴보기 거리 안에서 전투 중이 아닐 때 마우스를 올리면 장비로 계산합니다."
L["A profile"] = "프로필"
L["a quest"] = "퀘스트"
L["A quest reward for the other faction; try the Auction House."] = "다른 진영의 퀘스트 보상입니다. 경매장을 이용해 보세요."
L["A raid for %d players"] = "%d인 공격대"
L["A raid, a row each."] = "공격대, 한 명당 한 줄."
L["A rare someone else is fighting."] = "다른 사람이 싸우고 있는 희귀 몬스터."
L["A rare you have killed before."] = "이전에 처치한 희귀 몬스터."
L["A rare you have not killed yet."] = "아직 처치하지 않은 희귀 몬스터."
L["A reward from the quest "] = "다음 퀘스트의 보상:"
L["A ring around your cursor so you never lose it in a busy fight, with your global cooldown and casts swept around it."] = "바쁜 전투에서도 커서를 놓치지 않도록 커서 주위에 링을 표시하고, 전역 재사용 대기시간과 시전을 링에 회전으로 표시합니다."
L["A round in progress."] = "진행 중인 라운드."
L["A row of icons for missing food, flask, elixir and scroll buffs, your own class buff, and class buffs missing in your group. Out of combat only: the game keeps your buffs from addons in combat, so the icons keep what they showed. Hover one to pick a carried item to use. Move them in the HUD Editor."] = "빠진 음식, 영약, 비약, 두루마리 효과, 내 직업 강화 효과, 파티에 빠진 직업 강화 효과를 아이콘 줄로 표시합니다. 전투 중이 아닐 때만: 전투 중에는 게임이 애드온에 효과 정보를 숨기므로 아이콘이 마지막 상태를 유지합니다. 마우스를 올려 사용할 소지 아이템을 고르세요. HUD 편집기에서 옮기세요."
L["A running gold per hour beside the newest line, counting money and item value since your first loot this session."] = "최신 줄 옆에 이번 세션 첫 전리품 이후의 골드와 아이템 가치를 합산한 시간당 골드를 표시합니다."
L["A Scan Prices button on the auction house. It reads every listing and keeps the lowest buyout for each item, for this realm and faction. Blizzard allows one full scan every 15 minutes."] = "경매장에 가격 검색 버튼을 추가합니다. 모든 등록 물품을 읽고 이 서버와 진영의 아이템별 최저 즉시 구매가를 저장합니다. 블리자드는 15분마다 한 번 전체 검색을 허용합니다."
L["A junk icon on the bag slot of each item marked as junk."] = "잡동사니로 표시된 아이템의 가방 칸에 잡동사니 아이콘."
L["A second panel for your focus, to keep Sap or Polymorph's time on one enemy while you fight another."] = "주시 대상용 두 번째 패널로, 다른 적과 싸우는 동안 한 적에 걸린 기절시키기나 변이의 시간을 확인합니다."
L["A set that goes on by itself while you ride or rest, and the set you had on goes back afterwards."] = "탈것 탑승이나 휴식 중 자동으로 착용되는 세트. 끝나면 이전 세트로 돌아갑니다."
L["A shooting game for flights: click the other faction's races as fast as you can."] = "비행 중 사격 게임: 다른 진영의 종족을 최대한 빨리 클릭하세요."
L["A short flash of text entering and leaving combat. Move it in the HUD Editor."] = "전투에 들어가고 나올 때 잠깐 표시되는 텍스트. HUD 편집기에서 옮기세요."
L["A small bar with your next trainer visit and your gold, to leave up while you level. Move it by dragging."] = "다음 전문가 방문과 골드를 보여주는 작은 바로, 레벨업 중 띄워두기 좋습니다. 드래그해서 옮기세요."
L["A small health bar for the other tank in your group, shown while you are tanking: tank role, Bear Form, Defensive Stance or Righteous Fury. The other tank is whoever has the tank role or the raid's Main Tank assignment. Click it to target them. Changes made in combat apply when the fight ends. Move it in the HUD Editor."] = "내가 방어 전담 중일 때 파티의 다른 방어 전담 생명력 바를 작게 표시합니다: 방어 전담 역할, 곰 변신, 방어 태세, 정의의 격노. 다른 방어 전담은 방어 전담 역할이나 공격대 주 방어 전담 지정을 가진 사람입니다. 클릭하면 대상으로 지정합니다. 전투 중 변경은 전투가 끝나면 적용됩니다. HUD 편집기에서 옮기세요."
L["A soft glow around Naowh's arrow."] = "Naowh 화살표 주위의 부드러운 빛."
L["A soft glow beside each icon."] = "각 아이콘 옆의 부드러운 빛."
L["A soft glow round it in your accent color."] = "강조 색상의 부드러운 빛."
L["A soft glow round it in your rank's color."] = "등급 색상의 부드러운 빛."
L["A soft ring pulses around each target."] = "각 대상 주위에 부드러운 고리가 맥동합니다."
L["a sound to refresh"] = "갱신 알림 소리"
L["A sound, or the Speech text read aloud, as each cast starts."] = "각 시전이 시작될 때 소리 또는 음성 텍스트 읽기."
L["A sound, or the Speech text read aloud. Text to Speech can stutter on some PCs, as the game waits while Windows speaks it; a Sound costs nothing."] = "소리 또는 음성 텍스트 읽기. 일부 PC에서는 Windows가 읽는 동안 게임이 기다려서 음성 읽기가 끊길 수 있습니다. 소리는 부담이 없습니다."
L["A spell an import could not place because you do not know it yet goes into its saved slot when you learn it, unless you have put something else there."] = "아직 몰라서 가져오기가 배치하지 못한 주문은 배우면 저장된 칸에 들어갑니다. 그 칸에 다른 것을 넣었다면 제외됩니다."
L["A Stack button on the card when part-filled stacks of an item can be combined."] = "아이템의 덜 찬 묶음을 합칠 수 있을 때 카드에 겹치기 버튼을 표시합니다."
L["A star on the world map for every rare you have not killed, where it is most likely to be. Hover one for the rare and its drops, its other spawn spots and, if it patrols, its way; click it for a waypoint, right-click it to keep its spots and way shown."] = "아직 처치하지 않은 희귀 몬스터마다 출현 가능성이 가장 높은 위치에 세계 지도 별을 표시합니다. 마우스를 올리면 희귀 몬스터와 전리품, 다른 출현 지점, 순찰 경로를 보여줍니다. 클릭하면 경유지, 오른쪽 클릭하면 지점과 경로를 계속 표시합니다."
L["A string to share it with."] = "공유용 문자열."
L["A supporter"] = "후원자"
L["A team member"] = "팀원"
L["A text on the bar: click it on the preview to change it. Each text shows in one place on the bar: picking one shown elsewhere moves it there."] = "바 위의 텍스트: 미리보기에서 클릭해 변경하세요. 각 텍스트는 바의 한 곳에만 표시되며, 다른 곳에 있는 것을 고르면 그쪽으로 옮겨집니다."
L["A tick on the bar where your interrupt comes off cooldown. Hidden while it is ready."] = "차단 기술의 재사용 대기시간이 끝나는 지점에 바 눈금을 표시합니다. 준비되면 숨겨집니다."
L["A title bar naming the mob the threat is on."] = "위협 수준 대상 몹의 이름을 보여주는 제목 바."
L["A trained spell drops into its saved slot."] = "훈련한 주문이 저장된 칸에 들어갑니다."
L["a vendor sells the formula"] = "상인이 도안을 판매함"
L["A warning when a rare is near"] = "희귀 몬스터가 근처에 있을 때 경고"
L["A warning when a rare is near you: when its nameplate comes up, you mouse over it or target it. A card with its portrait: right-click it to close it, and its pin sets a waypoint to the rare. Move it in the HUD Editor."] = "희귀 몬스터가 근처에 있을 때 경고합니다: 이름표가 나타나거나, 마우스를 올리거나, 대상으로 지정할 때. 초상화가 있는 카드가 뜨며, 오른쪽 클릭으로 닫고 핀을 누르면 희귀 몬스터로 경유지를 설정합니다. HUD 편집기에서 옮기세요."
L["A warning while a hunter or warlock has no pet out. A warlock who sacrificed their demon is left alone. Move it in the HUD Editor."] = "사냥꾼이나 흑마법사가 소환수를 꺼내지 않았을 때 경고합니다. 악마를 희생한 흑마법사는 제외합니다. HUD 편집기에서 옮기세요."
L["A word of your own on the icon."] = "아이콘에 표시할 내 문구."
L["A world drop from %d kinds of mob"] = "몹 %d종에게서 얻는 월드 드롭"
L["A WoW quiz for campfires and flights, or any time with /naowh quiz."] = "모닥불과 비행 중, 또는 언제든 /naowh quiz로 즐기는 WoW 퀴즈."
L["A yellow ! on the world map at every quest giver with a quest you can pick up that still gives experience. Hover it for the quests; click it for a waypoint."] = "아직 경험치를 주는 수락 가능한 퀘스트가 있는 퀘스트 제공자마다 세계 지도에 노란 !를 표시합니다. 마우스를 올리면 퀘스트를, 클릭하면 경유지를 설정합니다."
L["A zone older than this is no longer shown, since the player has likely moved on."] = "이보다 오래된 지역은 플레이어가 이미 이동했을 가능성이 높아 표시하지 않습니다."
L["Abandon %s?"] = "%s(을)를 포기하시겠습니까?"
L["Abilities"] = "능력"
L["about "] = "약"
L["about %d:%02d"] = "약 %d:%02d"
L["About %s at your last scan%s%s"] = "마지막 검색 시 약 %s%s%s"
L["About %s spent"] = "약 %s 사용함"
L["About a minute."] = "약 1분."
L["Above"] = "위쪽"
L["Acc."] = "적중"
L["Accent: missing the class blessing. Lighter: running out. Deeper: only players with their own."] = "강조: 직업 축복 없음. 밝게: 곧 끝남. 진하게: 자신의 축복을 받은 플레이어만."
L["Accept Quests"] = "퀘스트 수락"
L["Accept Shared Dungeon Quests"] = "공유된 던전 퀘스트 수락"
L["Accepts a quest as soon as its text opens. Use the Modifier to read it first."] = "퀘스트 내용이 열리면 바로 수락합니다. 먼저 읽으려면 보조 키를 사용하세요."
L["Accepts dungeon quests your group shares with you straight away."] = "파티가 공유한 던전 퀘스트를 바로 수락합니다."
L["Accepts shared quests"] = "공유된 퀘스트 수락"
L["Accepts the popup on screen: a summons, a resurrection, a group invite."] = "화면의 팝업을 수락합니다: 소환, 부활, 파티 초대."
L["Accepts, hands in and shares quests for you, and remembers the reward you saved for a quest. The Modifier skips them or triggers them, as Modifier Does says."] = "퀘스트를 수락, 반납, 공유하고 퀘스트에 저장한 보상을 기억합니다. 보조 키는 보조 키 동작 설정에 따라 이를 건너뛰거나 실행합니다."
