L["Add an item ID, or import a list. Food counts any Well Fed buff and other items their own buff; add buff spell IDs only for an item that gives another. Nothing is added automatically. Hover a reminder to choose a configured item from your bags. Reminders pause in combat; item menus work outside combat. When and where they show is on AuraBuffs > Settings."] = "아이템 ID를 추가하거나 목록을 가져오세요. 음식은 포만감 효과를, 다른 아이템은 자체 효과를 확인합니다. 다른 효과를 주는 아이템에만 효과 주문 ID를 추가하세요. 자동으로 추가되는 것은 없습니다. 알림에 마우스를 올려 가방에서 설정된 아이템을 고르세요. 알림은 전투 중 멈추며, 아이템 메뉴는 전투 밖에서 작동합니다. 표시 시점과 위치는 AuraBuffs > 설정에 있습니다."
L["Add consumables, put them in order, and set each one up."] = "소비용품을 추가하고 순서를 정한 뒤 각각 설정하세요."
L["Add Items"] = "아이템 추가"
L["Add Latency"] = "지연 시간 포함"
L["Add macros someone shared with you."] = "다른 사람이 공유한 매크로를 추가합니다."
L["Add or remove your commands, turn each one on or off, or restore the defaults."] = "명령어를 추가하거나 제거하고, 각각 켜고 끄거나 기본값으로 복원합니다."
