L["Add the %s build %s (%d points)?"] = "%s 빌드 %s (%d 포인트)(을)를 추가할까요?"
L["Add the consumables to watch in the AuraBuffs window."] = "AuraBuffs 창에서 감시할 소비용품을 추가하세요."
