L["Add your own lines to the bag macros. They are kept after the item, whatever is in your bags."] = "가방 매크로에 직접 줄을 추가합니다. 가방 내용과 관계없이 아이템 뒤에 유지됩니다."
L["Added %d consumable to the Consumable Bar."] = "소비용품 %d개를 소비용품 바에 추가했습니다."
L["Added %d consumables to the Consumable Bar."] = "소비용품 %d개를 소비용품 바에 추가했습니다."
L["Added %d consumables; %d were already listed or past the %d limit."] = "소비용품 %d개 추가함. %d개는 이미 목록에 있거나 한도 %d개를 넘었습니다."
L["Added %d of %d: %s."] = "%d/%d개 추가: %s."
L["Added %d."] = "%d개 추가함."
L["Added %s to this character. Drag it to a bar from the game's macro window (/macro)."] = "이 캐릭터에 %s 추가함. 게임 매크로 창(/macro)에서 단축바로 드래그하세요."
L["Added %s to your BiS %s as #%d."] = "%s(을)를 %s BiS에 %d순위로 추가했습니다."
L["Added %s to your BiS %s."] = "%s(을)를 %s BiS에 추가했습니다."
L["Added next to your Library, never over it"] = "라이브러리에 덮어쓰지 않고 따로 추가됨"
L["Added next to your own lists, never over them"] = "내 목록에 덮어쓰지 않고 따로 추가됨"
L["Added next to your saved builds"] = "저장된 빌드 옆에 추가됨"
L["Adding Items"] = "아이템 추가 중"
