L["Addon Memory"] = "애드온 메모리"
L["Adds \"- [1] + Add to List\" under a recipe's reagents: the materials Buy on AH would buy for that many crafts go on a shopping list, from anywhere. At the auction house the list shows beside it: Check Prices looks each one up and warns in red when one is well above your last scan, then Buy All goes through the list one material at a time, each bought only when you confirm its final price. A material you can make for less from its parts, such as a bar from ore, has its parts bought instead."] = "제조법 재료 아래에 \"- [1] + 목록에 추가\"를 표시합니다: 경매장 구매로 그만큼 제작할 재료를 어디서든 구매 목록에 넣습니다. 경매장에서는 목록이 옆에 표시됩니다: 가격 확인은 각 재료를 조회해 마지막 검색보다 크게 비싸면 빨간색으로 경고하고, 모두 구매는 재료를 하나씩 진행하며 최종 가격을 확인할 때만 구매합니다. 광석으로 주괴를 만드는 것처럼 부품으로 더 싸게 만들 수 있는 재료는 부품을 대신 구매합니다."
L["Adds a Bags column to the chosen recipe's reagents, showing how many of each you carry."] = "선택한 제조법 재료에 가방 열을 추가해 각각 몇 개 가지고 있는지 표시합니다."
L["Adds a Bank column to the chosen recipe's reagents, showing how many of each are in your bank."] = "선택한 제조법 재료에 은행 열을 추가해 은행에 각각 몇 개 있는지 표시합니다."
L["Adds a button to the popup that swaps every lower rank on your bars for the highest rank you know. Keyboard and controller bars land in the same slot. Right-click a spell in the popup to keep its lower ranks, for downranking. Rank swaps only happen out of combat."] = "단축바의 모든 낮은 등급을 알고 있는 최고 등급으로 바꾸는 버튼을 팝업에 추가합니다. 키보드와 컨트롤러 단축바도 같은 칸에 들어갑니다. 등급 낮추기용으로 낮은 등급을 유지하려면 팝업에서 주문을 오른쪽 클릭하세요. 등급 교체는 전투 중이 아닐 때만 일어납니다."
L["Adds a Land button to come down at the next stop on the way."] = "가는 길의 다음 정류장에서 내리는 착지 버튼을 추가합니다."
L["Adds a line that flags any slot whose enchant is missing or differs from the ones you captured with Capture Current Enchants. Hover it for the details."] = "마법부여가 없거나 현재 마법부여 캡처로 저장한 것과 다른 칸을 알려주는 줄을 추가합니다. 마우스를 올려 자세히 보세요."
L["Adds a mana spell's healing or damage per mana and per second to its tooltip."] = "마나 주문 툴팁에 마나당, 초당 치유량 또는 피해량을 추가합니다."
L["Adds a second, orange number next to each recipe: how many you could make after buying the reagents vendors sell, such as Weak Flux or Coarse Thread. The recipe's reagents then say how many of each to buy."] = "각 제조법 옆에 주황색 숫자를 하나 더 표시합니다: 약한 융해제나 굵은 실처럼 상인이 파는 재료를 사면 만들 수 있는 개수입니다. 제조법 재료에는 각각 몇 개 사야 하는지 표시됩니다."
L["Adds how long the visit lasted."] = "방문 시간을 추가합니다."
L["Adds target and focus switching to the meter's title bar."] = "미터기 제목 바에 대상 및 주시 대상 전환을 추가합니다."
L["Adds the average experience here."] = "이곳의 평균 경험치를 추가합니다."
L["Adds the coins looted."] = "획득한 골드를 추가합니다."
L["Adds the consumables in your bags that are not on the bar yet."] = "아직 바에 없는 가방 속 소비용품을 추가합니다."
L["Adds the deaths."] = "사망 횟수를 추가합니다."
L["Adds the experience gained."] = "얻은 경험치를 추가합니다."
L["Adds the materials for one more craft."] = "한 번 더 제작할 재료를 추가합니다."
L["Adds the Naowh themes to RestedXP's theme list."] = "RestedXP 테마 목록에 Naowh 테마를 추가합니다."
L["Adds the reputation gained."] = "얻은 평판을 추가합니다."
L["Adds the visits at this level."] = "이 레벨에서의 방문 횟수를 추가합니다."
L["Adds the visits until you level."] = "레벨업까지 필요한 방문 횟수를 추가합니다."
L["Adds your bonus healing or spell damage; off shows the spell's base numbers."] = "치유량 또는 주문 공격력 보너스를 더합니다. 끄면 주문의 기본 수치를 표시합니다."
