L["After each fight longer than 15 seconds, how long you spent neither casting nor on the global cooldown, in chat."] = "15초보다 긴 전투가 끝날 때마다 시전도 전역 재사용 대기시간도 아니었던 시간을 대화창에 표시합니다."
L["after the 5% cut"] = "5% 수수료 차감 후"
L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "전문가를 방문한 후 방금 배운 능력을 작은 창에 표시합니다. 교본이나 퀘스트로 배운 능력은 잠시 후 표시됩니다. 창에서 단축바로 드래그하세요."
