L["Also keeps your last whispers and group chat lines with each player."] = "각 플레이어와의 마지막 귓속말과 파티 대화도 보관합니다."
L["Also opens the world map on the waypoint, so you see where it is. Out of combat only."] = "경유지 위치에 세계 지도도 열어 어디인지 보여줍니다. 전투 중이 아닐 때만."
L["Also prints the summary when you leave a raid."] = "공격대를 떠날 때도 요약을 출력합니다."
L["Also reminds you inside instances. Off by default: few have herbs or ore."] = "인스턴스 안에서도 알립니다. 약초나 광석이 있는 곳이 드물어 기본값은 꺼짐입니다."
L["Also shows each recipe's profit at the right of its row in the list, green or red. Recipes whose profit is not known show none."] = "목록의 각 제조법 줄 오른쪽에 이익을 초록색 또는 빨간색으로 표시합니다. 이익을 모르는 제조법은 표시하지 않습니다."
L["Also thanks players in your party or raid."] = "파티나 공격대의 플레이어에게도 감사를 표합니다."
L["Also used inside dungeons and raids."] = "던전과 공격대 안에서도 사용합니다."
L["Also warns about rares you have killed before."] = "이전에 처치한 희귀 몬스터도 경고합니다."
L["Also warns while your pet is set to passive."] = "소환수가 수동 상태일 때도 경고합니다."
L["Also warns while your pet's health is under the threshold, in combat too."] = "소환수의 생명력이 기준 미만일 때도 경고합니다 (전투 중 포함)."
L["Also worth a look"] = "이것도 볼 만함"
L["Alt"] = "Alt"
L["Alt + Shift"] = "Alt + Shift"
L["Alt Item Counts"] = "부캐릭터 아이템 개수"
L["Alt-click a reward you can choose, in the quest log or at the quest giver, to save it for that quest in this profile; Alt-click it again to clear it. It is selected when you hand the quest in, and Hand In Quests takes it for you."] = "퀘스트 목록이나 퀘스트 제공자에서 선택 가능한 보상을 Alt+클릭하면 이 프로필에 해당 퀘스트용으로 저장되고, 다시 Alt+클릭하면 해제됩니다. 퀘스트를 반납할 때 선택되며, 퀘스트 반납이 대신 받아줍니다."
L["Alt-click an item in your bags to mark it as junk, and sell it at the next vendor."] = "가방의 아이템을 Alt+클릭하면 잡동사니로 표시하고 다음 상인에게 판매합니다."
L["Alts Button on Mail"] = "우편함 부캐릭터 버튼"
L["Always"] = "항상"
L["always"] = "항상"
L["Always Sharpen"] = "항상 선명하게"
L["Always Show"] = "항상 표시"
L["always shown"] = "항상 표시됨"
L["Always, only in combat, or only out of combat."] = "항상, 전투 중에만, 또는 전투 중이 아닐 때만."
L["Ammo"] = "탄약"
L["Ammo to Carry"] = "휴대할 탄약"
L["Ammunition"] = "탄약"
L["An \"Inventory is full\" error brings the row up for 20 seconds, even with more free slots than the threshold above."] = "\"소지품이 가득 찼습니다\" 오류가 나면 위 기준보다 빈 칸이 많아도 20초간 줄을 표시합니다."
L["An alt that already has this macro, by name and text or text alone, uses its own."] = "이름과 내용 또는 내용만으로 같은 매크로를 이미 가진 부캐릭터는 자신의 것을 사용합니다."
L["An Alts button beside the mailbox's Send tab lists your characters on this realm and faction with their level and gold. Pick one to fill the To box."] = "우편함 보내기 탭 옆의 부캐릭터 버튼이 이 서버와 진영의 캐릭터를 레벨, 골드와 함께 보여줍니다. 하나를 고르면 받는 사람 칸이 채워집니다."
L["An Attach button beside the mailbox's Send tab: attach every trade good, one type of trade good, or your unbound gear in one click."] = "우편함 보내기 탭 옆의 첨부 버튼: 모든 직업용품, 한 종류의 직업용품, 또는 귀속되지 않은 장비를 한 번에 첨부합니다."
L["An ID the game keeps hidden: Hide Line leaves it off the tooltip, Show Hidden shows the line with Hidden in place of the number."] = "게임이 숨기는 ID: 줄 숨기기는 툴팁에서 빼고, 숨김 표시는 숫자 대신 숨김으로 줄을 표시합니다."
