L["Each class's name or icon, under its button or beside it when the bar is vertical."] = "각 직업 이름 또는 아이콘. 버튼 아래, 바가 세로면 옆에 표시."
L["Each dungeon or raid visit while Instance Tracker is on: how long you were inside, the coins you looted and the experience you gained. Reputation gained is listed under the visit. Coming back to the same group within the hour, before you reset it, continues that visit, and the time outside is not counted. Other characters stay saved, and show here when Track Alts is on. Repairs and vendor sales are not counted. Older visits drop off the end of the list."] = "인스턴스 추적기가 켜져 있는 동안의 던전 및 공격대 방문: 머문 시간, 획득한 골드, 얻은 경험치. 얻은 평판은 방문 아래에 표시됩니다. 초기화하기 전 1시간 안에 같은 파티로 돌아오면 같은 방문으로 이어지며 밖에 있던 시간은 세지 않습니다. 다른 캐릭터도 저장되며 부캐릭터 추적이 켜져 있으면 여기에 표시됩니다. 수리비와 상점 판매는 세지 않습니다. 오래된 방문은 목록 끝에서 사라집니다."
L["Each line fades out after %ss."] = "각 줄은 %s초 후 사라집니다."
L["Each one is an account macro. Put it on a bar once and it keeps itself current: loot a better potion, conjure fresh food or pick up bandages and the macro is rewritten to use the best you carry.\n\nThe game does not let macros change mid-fight, so a change during combat waits until it ends."] = "모두 계정 공용 매크로입니다. 단축바에 한 번 넣으면 스스로 최신 상태를 유지합니다: 더 좋은 물약을 얻거나, 새 음식을 창조하거나, 붕대를 주우면 가진 것 중 가장 좋은 것을 쓰도록 매크로가 다시 작성됩니다.\n\n게임은 전투 중 매크로 변경을 허용하지 않으므로 전투 중 변경은 전투가 끝날 때까지 기다립니다."
