L["Every setting now follows %s. Reload now to finish?"] = "이제 모든 설정이 %s(을)를 따릅니다. 지금 재시작해 마무리할까요?"
L["Every slot."] = "모든 칸."
L["every spell on your bars is at its highest rank."] = "단축바의 모든 주문이 최고 등급입니다."
