L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "성기사용으로 파티의 직업마다 버튼을 표시합니다. 왼쪽 클릭하면 축복이 필요한 해당 직업 파티원에게 없는 사람부터 축복하며, 죽었거나 사거리 밖인 사람은 건너뜁니다. 직업을 오른쪽 클릭하면 축복을 고르거나 플레이어 목록을 엽니다. HUD 편집기에서 옮기세요. 미리보기에서 편집: 직업 오른쪽 클릭으로 축복, 오라 클릭으로 선택, 휠로 크기, Shift+휠로 간격, 오라 뒤 간격 드래그, x로 버튼 숨기기, +로 다시 표시."
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Skyborne 캐릭터용: 지맥(얼라이언스, 지맥 읽기용) 또는 정기의 합일점(호드, 창공안용)을 세계 지도에 핀으로 표시합니다. 게임은 이를 표시하지 않습니다: 애드온은 플레이어들이 찾은 곳을 알고 있으며, 종족 특성을 시전한 새 장소를 저장합니다. 다른 종족에게는 핀이 보이지 않습니다."
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "내 직업용: 새 캐릭터가 경험치 없는 1레벨일 때 이 세트를 한 번 가져옵니다."
L["For your level"] = "내 레벨용"
L["Forget %s on %s? It comes back the next time you log in on it with a Mail & Alts option on."] = "%2$s의 %1$s(을)를 잊을까요? 우편 및 부캐릭터 옵션이 켜진 상태로 다음에 접속하면 다시 나타납니다."
