L["Hover a badged name in chat to see their card."] = "대화창에서 배지가 있는 이름에 마우스를 올리면 카드를 봅니다."
L["Hover a spell, item or NPC and press the shortcut to copy its ID. With Tooltips on it opens the copy card; with only Copy Command on, a box with the ID."] = "주문, 아이템, NPC에 마우스를 올리고 단축키를 누르면 ID를 복사합니다. 툴팁이 켜져 있으면 복사 카드를 열고, 복사 명령어만 켜져 있으면 ID가 있는 상자를 엽니다."
