L["How big the entrance icons are. They are largest on a zone's map, smaller on a continent's and the world's."] = "입구 아이콘의 크기. 지역 지도에서 가장 크고, 대륙과 세계 지도에서는 작습니다."
L["How big the on-screen alert is."] = "화면 경고의 크기."
L["How big the pins are on the map."] = "지도 핀의 크기."
