L["How big the stars are on the map."] = "지도 별의 크기."
L["How big the tracker is."] = "추적기의 크기."
L["How close a book has to be before it pings."] = "책이 얼마나 가까워야 알림이 울리는지."
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "현재 주문이 끝나기 전 다음 주문을 미리 누를 수 있는 시간(밀리초). 대부분 100~400이 적당합니다: 낮을수록 반응이 빠르고, 높을수록 지연 시간에 관대합니다. 근접은 핑 + 100, 원거리는 핑 + 150 정도."
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "아이콘이 흐려지기 시작하는 시점, 0%(즉시)부터 95%(맨 끝)까지."
L["How far below your level gear has to be for Old Common Gear."] = "오래된 일반 장비로 간주할 레벨 차이."
L["How Group Inspect shows a party and a raid, with sample players."] = "예시 플레이어로 보는 파티 살펴보기의 파티 및 공격대 표시."
L["How little Camp Benefits time counts as needing a refresh."] = "갱신이 필요하다고 볼 남은 이로운 야영 효과 시간."
L["How long an interrupted cast stays up. 0 hides it at once."] = "차단된 시전을 표시하는 시간. 0이면 바로 숨깁니다."
L["How long before the effect runs out it shows again."] = "효과가 끝나기 얼마 전에 다시 표시할지."
L["How long each line stays before it fades."] = "각 줄이 사라지기 전 유지되는 시간."
L["How long it takes to get there at your speed."] = "현재 속도로 도착까지 걸리는 시간."
L["How long the current fight has run, on screen while you fight. Move it in the HUD Editor."] = "전투 중 화면에 현재 전투 시간을 표시합니다. HUD 편집기에서 옮기세요."
L["How long the fight lasted, in chat when it ends."] = "전투가 끝나면 대화창에 전투 시간을 표시합니다."
L["How long the next level takes at your current rate."] = "현재 속도로 다음 레벨까지 걸리는 시간."
L["How long this session has run."] = "이번 세션 진행 시간."
L["How many crafts Add to List adds the materials for."] = "목록에 추가가 재료를 추가할 제작 횟수."
L["How many crafts Buy buys the materials for."] = "구매가 재료를 살 제작 횟수."
L["How many crafts to ask for."] = "요청할 제작 횟수."
L["How many decimals the per mana numbers show."] = "마나당 수치의 소수점 자릿수."
L["How many icons fit in a row before the next row starts."] = "다음 줄로 넘어가기 전 한 줄에 들어가는 아이콘 수."
L["How many new instances this account has entered this hour."] = "이번 시간에 이 계정이 입장한 새 인스턴스 수."
L["How many of this material you hand the crafter. Ticking the box fills in all the crafts need; - and + change it by one."] = "제작자에게 건넬 이 재료의 개수. 체크하면 모든 제작에 필요한 만큼 채우고, -와 +로 하나씩 바꿉니다."
L["How many to carry. 0 stops reminding you about it."] = "휴대할 개수. 0이면 알림을 멈춥니다."
L["How Much Stronger"] = "강해지는 정도"
