L["How solid the map's window, the Journal beside the map and Boss Loot at Cursor are."] = "지도 창, 지도 옆 도감, 커서 위치 우두머리 전리품의 불투명도."
L["How solid the planner's window is, in percent. Also on its title bar."] = "플래너 창의 불투명도(%). 제목 바에도 적용됩니다."
