L["On gear that is an upgrade for your spec, a line saying by how much (\"+9% upgrade\"). The BiS List uses these weights either way."] = "내 전문화에 향상인 장비에 얼마나 좋아지는지 한 줄 표시합니다 (\"+9% 향상\"). BiS 목록은 어느 쪽이든 이 가중치를 사용합니다."
