L["On-Screen Alert is off: Drop Alert plays its chat line and sounds only."] = "화면 경고가 꺼져 있음: 획득 경고는 대화창 메시지와 소리만 재생합니다."
L["On-Screen Buttons"] = "화면 버튼"
L["On. Click to turn the whole module off."] = "켜짐. 클릭하면 모듈 전체를 끕니다."
