L["Onboarding"] = "설정 안내"
L["Once Per Player Every"] = "플레이어당 한 번, 간격"
L["Once you have scanned the auction house (Scan Prices), the chosen recipe shows what its reagents cost to buy and what the item sells for, and the profit after the 5% auction house cut. Each reagent is priced at its cheapest: a vendor's price once you have seen a vendor sell it, else the lowest buyout at your last scan. Uncheck a reagent you already have to leave it out of the cost, for every recipe that uses it. Hover the lines for the breakdown."] = "경매장을 검색(가격 검색)하면 선택한 제조법의 재료 구매 비용, 아이템 판매가, 경매장 수수료 5%를 뺀 이익을 표시합니다. 각 재료는 최저가로 계산합니다: 상인이 파는 것을 본 적이 있으면 상인 가격, 아니면 마지막 검색의 최저 즉시 구매가. 이미 가진 재료는 체크를 해제하면 그 재료를 쓰는 모든 제조법의 비용에서 빠집니다. 줄에 마우스를 올리면 세부 내역을 봅니다."
L["One addon"] = "하나의 애드온으로"
L["One bar per weapon, timed by the game's own swing event, so parry haste, swing resets and haste are always right. Move them in the HUD Editor."] = "무기마다 바 하나. 게임 자체 공격 이벤트로 시간을 재므로 막기 가속, 공격 초기화, 가속이 항상 정확합니다. HUD 편집기에서 옮기세요."
L["One Fewer"] = "하나 빼기"
L["One item per click: the game needs a click for every disenchant."] = "클릭당 아이템 하나: 게임은 마력 추출마다 클릭이 필요합니다."
L["One More"] = "하나 더"
L["One number for a character's gear, on the item level scale: 26.4 means gear worth a set of level 26 epics. Your own is always on the BiS List's paperdoll."] = "캐릭터 장비를 아이템 레벨 척도로 나타낸 숫자: 26.4는 26레벨 영웅 장비 한 벌에 해당합니다. 내 점수는 항상 BiS 목록의 캐릭터 그림에 있습니다."
L["One whisper per line, picked at random; {buff} and {name} are filled in."] = "한 줄에 귓속말 하나, 무작위 선택. {buff}와 {name}이 채워집니다."
L["Online"] = "접속 중"
L["Only %d listed right now."] = "지금 %d개만 등록되어 있습니다."
L["Only buffs a dispel or purge can take off."] = "해제나 정화로 없앨 수 있는 강화 효과만."
L["Only Buffs I Can Cast"] = "내가 걸 수 있는 강화 효과만"
L["Only count food and drink whose required level is within this range."] = "요구 레벨이 이 범위 안인 음식과 음료만 셉니다."
L["Only If I Carry One"] = "소지 중일 때만"
L["Only In a Group"] = "파티 중에만"
L["Only In Combat"] = "전투 중에만"
L["Only In Dungeons & Raids"] = "던전 및 공격대에서만"
L["Only In Instances"] = "인스턴스에서만"
L["Only in its window"] = "전용 창에서만"
L["Only Magic Buffs"] = "마법 강화 효과만"
L["Only quest chains: the first quest of each one, and the next step of those you are on."] = "연계 퀘스트만: 각 연계의 첫 퀘스트와 진행 중인 연계의 다음 단계."
L["Only the gear that beats what you wear: a higher pick on your BiS list, or a higher item level you can wear."] = "착용 장비보다 나은 장비만: BiS 목록 순위가 더 높거나, 착용 가능한 더 높은 아이템 레벨."
L["Only the group leader can disband the group."] = "파티장만 파티를 해산할 수 있습니다."
L["Only the group leader or an assistant can plan every paladin's blessings."] = "파티장이나 부공대장만 모든 성기사의 축복을 계획할 수 있습니다."
L["Only the loot you still need from your BiS list: higher on it than what you wear, and not in your bags or bank."] = "BiS 목록에서 아직 필요한 전리품만: 착용 장비보다 순위가 높고 가방이나 은행에 없는 것."
L["Only the loot your class can use. Off, the rest is listed faded."] = "내 직업이 쓸 수 있는 전리품만. 끄면 나머지는 흐리게 표시됩니다."
L["Only the macros on your kept slots come along."] = "보관한 칸의 매크로만 포함됩니다."
L["Only the recipes for the professions you have. Off, every recipe is listed."] = "내가 가진 전문 기술의 제조법만. 끄면 모든 제조법을 표시합니다."
L["Only the scores shared over your guild."] = "길드에서 공유된 점수만."
L["Only the sweep and the ready ring show."] = "회전과 준비 링만 표시."
L["Only when you open it"] = "열 때만"
L["Only With Free Slots Below"] = "빈 칸 부족 기준 이하일 때만"
L["Only with Show In Combat"] = "전투 중 표시일 때만"
L["Onto %s, level %d %s. Saved %s%s."] = "%s 대상: %d레벨 %s. %s%s 저장됨."
