L["The key that opens the Journal."] = "도감을 여는 키."
L["The key that opens the Quest List window."] = "퀘스트 목록 창을 여는 키."
L["The last %ds, scrolling %s%s"] = "최근 %d초, %s%s 방향으로 스크롤"
L["The last fight's time stays on screen until the next one starts."] = "다음 전투가 시작될 때까지 마지막 전투 시간이 화면에 남습니다."
L["The last part of each melee swing, shaded."] = "각 근접 공격 주기의 마지막 부분을 음영 표시."
L["the last profile cannot be deleted"] = "마지막 프로필은 삭제할 수 없음"
L["The last profile cannot be deleted."] = "마지막 프로필은 삭제할 수 없습니다."
L["The latest %d kills. First counted: %s."] = "최근 처치 %d회. 첫 집계: %s."
L["The latest %d. First counted: %s."] = "최근 %d회. 첫 집계: %s."
L["The leader's zone on each Group Finder listing, and every member's zone when you hover it."] = "파티 찾기 목록마다 파티장의 지역을, 마우스를 올리면 모든 파티원의 지역을 표시합니다."
L["The level you are on as it runs, then completed levels, newest first."] = "진행 중인 현재 레벨, 그다음 완료한 레벨을 최신순으로."
L["The line round the bar."] = "바 주위의 선."
L["The list this character uses."] = "이 캐릭터가 사용하는 목록."
L["The longest a buff can last to show; longer ones like Arcane Intellect stay hidden."] = "표시할 강화 효과의 최대 지속시간. 신비한 지능처럼 긴 효과는 숨겨집니다."
L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "비전투 시 애드온이 작성하고 최신 상태로 유지하는 매크로. 여기서 켜거나 Naowh's Forge의 스마트 매크로에서 단축바로 가져가세요."
L["The macros you saved to the Forge's Library."] = "Forge 라이브러리에 저장한 매크로."
L["The Man. The King."] = "그 남자. 그 왕."
L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "지도 창, 세계 지도 옆 도감, 커서 위치 우두머리 전리품."
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "Naowh 캐릭터 창 없이 게임 자체 캐릭터 창(또는 EllesmereUI)에 표시합니다. Naowh 캐릭터 창을 켜면 그 칸에 이미 표시됩니다."
L["The Middle-click line."] = "휠 클릭 줄."
L["The most recent completed levels."] = "가장 최근 완료한 레벨."
L["the name is empty"] = "이름이 비어 있음"
L["The name on it, and the community it is made for."] = "이름과 대상 커뮤니티."
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "미니맵의 Naowh Forever 버튼. 애드온 보관함 항목과 /naowh로도 이 창을 열 수 있습니다."
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "대화창에서 Naowh, 개발자, 운영진, 전설 및 영웅 후원자 이름 옆에 표시되는 Naowh Forever N."
L["The newest line stays at the anchor; older lines stack in this direction."] = "최신 줄은 기준점에 남고, 이전 줄은 이 방향으로 쌓입니다."
L["The next one frees in "] = "다음 자리 비는 시간:"
L["the next rank of %s (cap %d)"] = "%s 다음 등급 (최대 %d)"
L["The number on each icon counts your bank as well as your bags."] = "각 아이콘의 숫자는 가방과 은행을 함께 셉니다."
L["The order the points are taken in"] = "포인트를 찍는 순서"
L["the pattern"] = "도안"
L["The people and projects behind Naowh Forever."] = "Naowh Forever를 만든 사람들과 프로젝트."
L["The picked boss's loot and abilities, under the map."] = "선택한 우두머리의 전리품과 능력, 지도 아래 표시."
L["The planner's own window, and a mini bar to leave up while you level."] = "플래너 전용 창과 레벨업 중 띄워둘 미니 바."
L["The player list opens after combat."] = "플레이어 목록은 전투 후에 열립니다."
L["The player's guild rank beside their guild name."] = "길드 이름 옆에 플레이어의 길드 등급."
L["The point of the bar that attaches."] = "붙는 바의 기준점."
L["The point of the frame it attaches to."] = "붙을 프레임의 기준점."
L["The purchase failed."] = "구매에 실패했습니다."
L["The purchase failed; the price may have changed."] = "구매에 실패했습니다. 가격이 바뀌었을 수 있습니다."
L["The purchase failed; the price may have changed.|r"] = "구매에 실패했습니다. 가격이 바뀌었을 수 있습니다.|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "퀘스트 추적기와 파티와의 던전 퀘스트 공유."
L["The quests that reward a pick you do not have yet."] = "아직 없는 선택 아이템을 보상으로 주는 퀘스트."
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "모닥불에 앉으면 퀴즈가 열리고 일어나면 닫힙니다."
L["The raid marker Mark Focus puts on your focus."] = "주시 대상 표시가 주시 대상에 붙이는 공격대 징표."
L["the rank before"] = "이전 등급"
L["The ready ring shows with GCD Sweep on."] = "준비 링은 전역 재사용 대기시간 회전이 켜져 있을 때 표시됩니다."
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "신비한 가루, 양초, 씨앗, 왕의 징표, 섬광 가루처럼 알고 있는 주문이 쓰는 재료를 알고 있는 최고 등급에 맞춰 계산합니다."
L["The red time left blinks, to catch your eye."] = "빨간 남은 시간이 깜빡여 눈길을 끕니다."
L["The same required-level filter applies to every stack, not each item separately."] = "요구 레벨 필터는 아이템별이 아니라 모든 묶음에 똑같이 적용됩니다."
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "캐릭터 창과 같은 세트: 장비 세트 창에서 착용, 저장, 이름 변경, 삭제하세요."
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "왕의 징표를 가지고 있으면 한 가지 축복을 공유하는 직업에 상급 축복으로 같은 작업을 합니다."
L["The seconds left when the time turns red; it turns yellow at twice that."] = "시간이 빨간색으로 바뀌는 남은 초. 그 두 배에서 노란색이 됩니다."
L["The serializer libraries are missing from this build."] = "이 빌드에 직렬화 라이브러리가 없습니다."
L["The shape of Naowh's arrow."] = "Naowh 화살표 모양."
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "권장 팁이 제작자 재료비 외에 추가하는 아이템 판매가 비율. 0으로 정하지 않으면 최소 1실버."
L["The shortest time between two thanks to the same player."] = "같은 플레이어에게 감사를 보내는 최소 간격."
L["The Slot"] = "칸"
L["The slot it is for."] = "해당 칸."
L["The slots and stats only"] = "칸과 능력치만"
L["The space between Naowh's arrow and the text under it."] = "Naowh 화살표와 아래 텍스트 사이 간격."
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "장비 가치를 계산할 전문화. 자동은 특성을 따릅니다: 포인트가 가장 많은 트리 (드루이드 야성은 공격 기준이며, 곰은 야성 방어 전담을 고르세요)."
L["The spot ahead of you, 312 yards away."] = "앞쪽 312미터 거리의 지점."
L["The spot off to your right."] = "오른쪽에 있는 지점."
L["The stat weights each spec starts with."] = "각 전문화의 기본 능력치 가중치."
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "은신하지 않았을 때의 알림과 함께 은신 중일 때 은신 텍스트도 표시."
L["The step and distance text under RestedXP's waypoint arrow."] = "RestedXP 경유지 화살표 아래 단계와 거리 텍스트."
L["The string is damaged: copy it again in full."] = "문자열이 손상되었습니다: 전체를 다시 복사하세요."
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "권장 팁은 제작자 재료비에 아이템 판매가의 %d%%(아이템을 만들지 않는 제조법은 전체 재료 기준)를 더해 반올림하며 최소 1실버입니다. 오른쪽 주문 목록에서 직접 팁을 정하세요. 비율은 전문 기술 설정에서 바꾸세요."
L["The swing timer needs WoW: Forever's own swing event."] = "자동 공격 타이머에는 WoW: Forever 자체 공격 이벤트가 필요합니다."
L["The tag in the speaker's class color. Off, it is grey."] = "말한 사람의 직업 색상으로 태그 표시. 끄면 회색입니다."
L["the talent above it"] = "위쪽 특성"
L["The talent builds you saved in the Training Planner."] = "훈련 플래너에 저장한 특성 빌드."
L["The Team"] = "제작진"
L["The text in the theme's accent color instead of gold."] = "금색 대신 테마 강조색 텍스트."
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "RestedXP가 쓰는 테마: 자체 테마 또는 Naowh 테마 중 하나."
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "양쪽 사이의 시간. 클릭하면 달력을 엽니다 (게임패드 제외)."
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "남은 시간이 노란색, 끝 무렵 빨간색으로 바뀌어 군중 제어가 곧 풀리는 것을 보여줍니다."
L["The time left, turning yellow, then red, as the camp runs down."] = "야영 시간이 줄어들수록 남은 시간이 노란색, 빨간색으로 바뀝니다."
L["The tint on every button's icon: Naowh's own and any addon's."] = "모든 버튼 아이콘의 색조: Naowh와 다른 애드온 모두."
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "레벨업 중 훈련 플래너의 도움: 배울 주문이 있을 때 레벨업 알림, 직업 전문가 옆 패널."
L["The unit frame the bar is attached to, or UIParent for the screen."] = "바가 붙은 유닛 프레임, 또는 화면 기준인 UIParent."
L["The weights"] = "가중치"
L["The weights for %s."] = "%s 가중치."
L["The window's border fades with it."] = "창 테두리도 함께 흐려집니다."
L["The word itself."] = "단어 자체."
L["The XP of completed quests, and their text."] = "완료한 퀘스트의 경험치와 텍스트."
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "진행 중인 퀘스트의 경험치를 완료한 퀘스트 뒤에 흐린 구간으로."
L["The XP of quests still in progress. By default the completed quests color, faded."] = "진행 중인 퀘스트의 경험치. 기본값은 완료한 퀘스트 색상을 흐리게."
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "대화 채널, 길드 대화, 귓속말로 말한 사람의 지역을 메시지 앞에 표시합니다. 게임은 낯선 사람의 위치를 알려주지 않으므로 파티 찾기, 길드, 친구, 파티에 있거나, /who에 나왔거나, 자신의 Naowh Forever로 응답한 후에 표시됩니다. 첫 메시지는 표시 없이 올 수 있습니다."
