L["What a zone's page in the Quest List window lists."] = "퀘스트 목록 창의 지역 페이지에 표시할 것."
L["What a zone's page in the Quest List window lists. Kills count from when Discovery is on: Shift-click a rare there to tick off one you killed before."] = "퀘스트 목록 창의 지역 페이지에 표시할 것. 처치는 발견을 켠 시점부터 집계됩니다: 이전에 처치한 희귀 몬스터는 거기서 Shift+클릭해 체크하세요."
L["What changed in recent builds."] = "최근 빌드의 변경 사항."
L["WHAT COMES ACROSS"] = "포함되는 것"
L["What drops in every dungeon and raid."] = "모든 던전과 공격대의 전리품."
L["What each line is worth, in gold, silver and copper."] = "각 줄의 가치 (골드, 실버, 코퍼)."
L["What each stack is worth, in its largest coin, under its icon."] = "각 묶음의 가치를 가장 큰 화폐 단위로 아이콘 아래에 표시."
L["What each stat is worth to your spec: change them as you like."] = "내 전문화에서 각 능력치의 가치: 원하는 대로 바꾸세요."
L["What each stat is worth to your spec: the BiS List's upgrade percents and enchants come from them. Change the weights in the Stat Weights window, from the scales on the BiS List's title bar."] = "내 전문화에서 각 능력치의 가치: BiS 목록의 향상 비율과 마법부여가 여기서 나옵니다. BiS 목록 제목 바의 저울 아이콘으로 여는 능력치 가중치 창에서 바꾸세요."
L["What each stat is worth to your spec: the upgrade percents and enchants come from them. Set your own."] = "내 전문화에서 각 능력치의 가치: 향상 비율과 마법부여가 여기서 나옵니다. 직접 정하세요."
L["What Happened"] = "일어난 일"
L["What happens when you open a vendor. Both work whether or not the Restock Reminder is on."] = "상인을 열 때 할 동작. 둘 다 보충 알림 여부와 관계없이 작동합니다."
