L["What you can train now, what each level brings and what it costs."] = "지금 배울 수 있는 것, 레벨별로 얻는 것과 비용."
L["What you pay the crafter for this craft, sent with the whisper. Filled in with the suggested tip; type your own as 2g 50s, 75s or 2.5 (gold). Empty it to go back to the suggestion."] = "이 제작에 대해 제작자에게 줄 금액으로, 귓속말과 함께 보냅니다. 권장 팁으로 채워지며, 2g 50s, 75s, 2.5(골드)처럼 직접 입력하세요. 비우면 권장 금액으로 돌아갑니다."
L["What you wear that takes a better enchant for your level."] = "현재 레벨에 더 좋은 마법부여가 가능한 착용 장비."
L["What your target is doing in a fight: their short buffs and the crowd control on them."] = "전투 중 대상의 상태: 짧은 강화 효과와 걸린 군중 제어."
