L["Your BiS List's slot marks on the items in your bags: item level, your BiS's star, Forever's mark and the green arrow on an upgrade. In the game's bags or EllesmereUI's."] = "가방 속 아이템에 BiS 목록 칸 표시: 아이템 레벨, BiS 별, Forever 표시, 향상 시 초록 화살표. 게임 가방 또는 EllesmereUI 가방에 표시."
L["Your BiS lists, for every class."] = "모든 직업의 BiS 목록."
L["Your BiS only"] = "BiS만"
L["Your BiS you do not have yet: where to go next."] = "아직 없는 BiS: 다음 행선지."
L["Your BiS's star on a slot, and Forever's mark on what is new in Forever."] = "칸의 BiS 별과 Forever 신규 아이템의 Forever 표시."
L["Your BiS, your second pick, and so on."] = "BiS, 두 번째 선택 등."
L["Your buttons and a clock along the top."] = "위쪽에 버튼과 시계."
L["Your buttons on either side of an optional clock, with FPS and latency underneath."] = "선택형 시계 양쪽에 버튼, 아래에 FPS와 지연 시간."
L["Your buttons on either side of an optional clock, with FPS and latency underneath. Arrange the buttons in the preview: drag one to move it, its x removes it, a side's + adds one. Move the bar in the HUD Editor."] = "선택형 시계 양쪽에 버튼, 아래에 FPS와 지연 시간. 미리보기에서 버튼 배치: 드래그로 이동, x로 제거, 각 쪽의 +로 추가. HUD 편집기에서 바를 옮기세요."
L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "야영 보너스와 남은 시간을 화면에 표시하고 이로운 야영 효과가 끝나면 알립니다."
L["Your camp's bonuses by the icon, always or while you hover it."] = "아이콘 옆에 야영 보너스를 항상 또는 마우스를 올릴 때 표시."
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "최대 숙련도는 %d입니다.\n먼저 퀘스트 %s%s|r(을)를 완료하세요 (%s숙련도 %d):"
L["Your cap is %d.\nFirst read %s (needs skill %d):"] = "최대 숙련도는 %d입니다.\n먼저 %s(을)를 읽으세요 (숙련도 %d 필요):"
L["Your cap is %d.\nFirst train %s (%s, needs skill %d):"] = "최대 숙련도는 %d입니다.\n먼저 %s(을)를 배우세요 (%s, 숙련도 %d 필요):"
L["Your cast ends before the swing comes due."] = "공격 시점 전에 시전이 끝납니다."
L["Your cast will still be going as the swing comes due."] = "공격 시점에도 시전이 계속됩니다."
L["Your casts and channels swept around the ring too."] = "시전과 정신 집중도 링에 회전으로 표시."
L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "BiS 목록 스타일의 캐릭터 창(C): 칸별 표시, 내 전문화 능력치, 레벨 아래 Naowh 점수. 게임은 창과 모든 기능을 그대로 유지합니다. EllesmereUI 사용 시 이것을 켜면 재시작 후 그쪽 캐릭터 창이 꺼지고, 끄면 다시 켜집니다."
L["Your Characters"] = "내 캐릭터"
L["Your characters at level %d"] = "%d레벨의 내 캐릭터"
L["Your characters at level %d (%s)"] = "%d레벨의 내 캐릭터 (%s)"
L["Your characters on this realm and faction, remembered across your account: what they hold on item tooltips, and help at the mailbox."] = "계정 전체에서 기억하는 이 서버와 진영의 캐릭터: 아이템 툴팁의 보유 수량, 우편함 도우미."
L["Your Chat"] = "내 대화창"
L["Your chat only"] = "내 대화창에만"
