L["Your class macros and the Macros settings."] = "내 직업 매크로와 매크로 설정."
L["Your class's BiS lists"] = "내 직업 BiS 목록"
L["Your class's trainers only."] = "내 직업 전문가만."
L["Your code to claim your badge, the same as /nf badges id."] = "배지를 받는 코드, /nf badges id와 같습니다."
L["Your Color"] = "내 색상"
L["Your consumables on a bar you can click."] = "클릭할 수 있는 바에 소비용품 표시."
