L["your debuffs"] = "내 약화 효과"
L["Your equipment sets, the same ones the character sheet keeps."] = "캐릭터 창과 같은 장비 세트."
L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "작은 카드에 시간당 경험치, 레벨업까지 시간, 플레이 시간, 세션 길이, 최근 레벨 시간을 표시합니다. 최고 레벨에서 숨김. 마우스를 올려 시작, 일시 정지, 초기화 (/naowh xp start, pause, reset도 가능). HUD 편집기에서 옮기세요."
L["Your experience. Its left end is a darker shade."] = "경험치. 왼쪽 끝은 더 진한 색입니다."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "카드에 비행 정보: 남은 시간, 경로의 정류장, 다음 정류장."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "주시 대상의 시전을 별도 바에 표시하며, 차단 기술 준비 여부로 색을 바꾸고, 재사용 대기시간이 끝나는 지점에 눈금을, 차단할 수 없는 시전에는 방패를 표시합니다. 차단 기술은 자루 공격, 방패 가격, 발차기, 마법 차단, 대지 충격, 침묵, 야성의 돌진 중 처음 아는 것입니다. HUD 편집기에서 옮기세요."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "직업 색상의 주시 대상 이름과 패널 위의 직업 아이콘."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "NF Focus로 지정한 주시 대상: 다른 적과 싸우는 동안에도 타이머가 계속 흐릅니다."
L["Your game macros, not the Smart Macros, as one string to share."] = "스마트 매크로를 제외한 게임 매크로를 공유용 문자열 하나로."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "링에 전역 재사용 대기시간 회전, 끝나면 준비 링."
L["YOUR GOLD"] = "내 골드"
L["Your group in range: who is missing a blessing, who is running out, and who only needs their own."] = "범위 안의 파티: 축복이 없는 사람, 곧 끝나는 사람, 자신의 축복만 필요한 사람."
L["Your group on a boss you are tanking."] = "내가 방어 전담 중인 우두머리에 대한 파티."
L["Your group's bars, with sample members."] = "예시 파티원으로 보는 파티 바."
