L["Your group's healers and their mana, lowest first."] = "파티의 치유 전담과 마나, 낮은 순."
L["Your group's Naowh Score, gear, talents and stats."] = "파티의 Naowh 점수, 장비, 특성, 능력치."
L["Your group's threat on your target."] = "대상에 대한 파티의 위협 수준."
L["Your healers' mana, with sample healers."] = "예시 치유 전담으로 보는 치유 전담 마나."
L["Your health under the threshold, with a healing item in your bags."] = "생명력이 기준 아래이고 가방에 치유 아이템이 있음."
