L["Your keys stay as they are."] = "키가 그대로 유지됩니다."
L["Your level, experience and percentage on one bar, with the XP of completed quests and rested experience drawn past the fill. Replaces Blizzard's experience bar while it is on. Move it in the HUD Editor. Ctrl + right-click the bar to reset the session time and XP/Hour."] = "레벨, 경험치, 비율을 한 바에 표시하며, 완료한 퀘스트 경험치와 휴식 경험치를 채움 뒤에 그립니다. 켜져 있으면 블리자드 경험치 바를 대체합니다. HUD 편집기에서 옮기세요. 바를 Ctrl+오른쪽 클릭하면 세션 시간과 시간당 경험치를 초기화합니다."
L["Your List"] = "내 목록"
L["Your list's marks on items out in the game."] = "게임 내 아이템에 내 목록 표시."
