L["Your Materials"] = "내 재료"
L["Your materials"] = "내 재료"
L["Your Naowh Score, big under your level: hover it for your score with your BiS and the best in the game, click it for the BiS List."] = "레벨 아래 크게 표시되는 Naowh 점수: 마우스를 올리면 BiS 착용 시 점수와 게임 최고 점수를, 클릭하면 BiS 목록을 엽니다."
L["Your note on %s"] = "%s에 대한 내 메모"
