L["Your Rank"] = "내 계급"
L["Your rank this season, and what each rank gives."] = "이번 시즌 내 계급과 계급별 보상."
L["Your rank's color (BiS orange)"] = "등급 색상 (BiS 주황색)"
L["Your recent casts as icons scrolling away from a point, with a bar underneath while you were casting or on the global cooldown. Gaps in the bar are time spent doing nothing. Move it in the HUD Editor."] = "최근 시전을 기준점에서 흘러가는 아이콘으로 표시하고, 시전 중이거나 전역 재사용 대기 중일 때 아래에 바를 표시합니다. 바의 빈 곳은 아무것도 하지 않은 시간입니다. HUD 편집기에서 옮기세요."
L["YOUR ROAD TO 60"] = "60까지의 여정"
L["Your second pick"] = "두 번째 선택"
L["your second pick"] = "두 번째 선택"
L["Your settings are back. Reload now to finish?"] = "설정이 복원되었습니다. 지금 재시작해 마무리할까요?"
