L["Your spec's stats with what each is worth, or all of the game's stats."] = "내 전문화의 능력치와 각 가치, 또는 게임의 모든 능력치."
L["Your star and rank on the game's roll frame."] = "게임 주사위 창에 내 별과 순위."
L["YOUR STATS"] = "내 능력치"
L["Your supporter badge, big in the panel's top corner, if you have one."] = "후원자 배지가 있으면 패널 위쪽 모서리에 크게 표시."
L["Your swings from the game's own swing timer, with marks for timing around them."] = "게임 자체 공격 타이머의 내 공격 주기와 타이밍 표시."
L["Your swings, with marks to time around them."] = "타이밍 표시가 있는 내 공격 주기."
