L["Your target's "] = "대상의"
L["Your target's buffs that last a short while, like Divine Shield, Evasion or Sprint."] = "천상의 보호막, 회피, 전력 질주처럼 짧게 지속되는 대상의 강화 효과."
L["Your target's short buffs and crowd control."] = "대상의 짧은 강화 효과와 군중 제어."
L["Your target's short buffs, the crowd control on them and the debuffs you pick, as large icons that keep working in combat."] = "대상의 짧은 강화 효과, 걸린 군중 제어, 고른 약화 효과를 전투 중에도 작동하는 큰 아이콘으로."
L["Your target's swing, restarted by its last hit on you."] = "대상의 공격 주기, 나에게 마지막으로 적중할 때 다시 시작."
L["Your tip:"] = "내 팁:"
