L["Your trinkets, weapons and ranged slot in a small window when you enter a dungeon or raid, or on a ready check, so a wrong trinket gets noticed before the pull. Drag the window to move it."] = "던전이나 공격대에 들어가거나 준비 확인 시 장신구, 무기, 원거리 칸을 작은 창에 표시해 전투 전에 잘못된 장신구를 알아챌 수 있게 합니다. 창을 드래그해 옮기세요."
L["Your two trinket slots, movable: left-click to use one, right-click to equip a trinket from your bags outside combat. Move it in the HUD Editor."] = "옮길 수 있는 장신구 칸 두 개: 왼쪽 클릭으로 사용, 비전투 시 오른쪽 클릭으로 가방의 장신구 착용. HUD 편집기에서 옮기세요."
